SELECT CASE WHEN (SELECT COUNT(*)=23 FROM expected e
JOIN song_masters sm ON sm.id IS e.master_id AND sm.artist_id IS e.artist_id AND sm.album_artist_id IS e.album_artist_id AND sm.title IS e.title AND sm.sort_title IS e.sort_title AND sm.track IS e.track AND sm.duration IS e.duration AND sm.genre IS e.genre AND sm.album_id IS (CASE WHEN e.suffix='flac' THEN 'al-8b7626106c' ELSE 'al-1aee8da1c9' END) AND sm.disc IS (CASE WHEN e.suffix='flac' THEN 1 ELSE e.disc END)
JOIN song_instances si ON si.id IS e.instance_id AND si.master_id IS e.instance_master_id AND si.source_id IS e.source_id AND si.source_type IS e.source_type AND si.storage_uri IS e.storage_uri AND si.storage_object_id IS e.storage_object_id AND si.suffix IS e.suffix AND si.size IS e.instance_size AND si.missing IS e.missing AND si.tag_scanned IS e.tag_scanned
JOIN storage_objects so ON so.id IS e.object_id AND so.physical_key IS e.physical_key AND so.size IS e.object_size
JOIN storage_entries se ON se.id IS e.entry_id AND se.source_id IS e.entry_source_id AND se.parent_id IS e.parent_id AND se.path IS e.path AND se.kind IS e.kind AND se.instance_id IS e.entry_instance_id AND se.object_id IS e.entry_object_id) AND (SELECT COUNT(*)=12 AND COUNT(DISTINCT track)=12 AND MIN(track)=1 AND MAX(track)=12 FROM song_masters WHERE album_id='al-1aee8da1c9' AND disc=1) AND (SELECT COUNT(*)=11 AND COUNT(DISTINCT track)=11 AND MIN(track)=2 AND MAX(track)=12 FROM song_masters WHERE album_id='al-8b7626106c' AND disc=1) AND (SELECT song_count=12 AND duration=2775 AND size=44989327 AND compilation=1 AND name='Sweet Sugar' AND cover_r2_key='covers/al-1aee8da1c9' FROM albums WHERE id='al-1aee8da1c9') AND (SELECT song_count=11 AND duration=2738 AND size=365724208 AND compilation=0 AND name='Sweet Sugar (FLAC)' AND cover_r2_key='covers/al-8b7626106c' FROM albums WHERE id='al-8b7626106c') AND (SELECT COUNT(*)=2 FROM album_display_group_members WHERE group_id='ag-sweet-sugar-editions-20260926') AND (SELECT sort_order=0 FROM album_display_group_members WHERE group_id='ag-sweet-sugar-editions-20260926' AND album_id='al-1aee8da1c9') AND (SELECT sort_order=1 FROM album_display_group_members WHERE group_id='ag-sweet-sugar-editions-20260926' AND album_id='al-8b7626106c') THEN 1 ELSE abs(-9223372036854775808) END;
